async () => {
      if (UI.failNext('credentials')) {
        sessionStorage.setItem('dujia-prototype-login-phone', phone.value.replace(/\s/g, ''));
        sessionStorage.setItem('dujia-prototype-login-attempts', '4');
        return UI.go('m01-p06.html', {force: true});
      }
      if (sessionStorage.getItem('dujia-prototype-fail-next') === 'login') {
        sessionStorage.removeItem('dujia-prototype-fail-next');
        throw new Error('登录没有完成，请检查网络后重试');
      }
      if (!await window.PrototypePreferences.login(phone.value.replace(/\s/g, ''))) return false;
      UI.toast('已进入你的故事', 'success');
      const relationship = UI.read('dujia-prototype-relationship');
      location.href = relationship?.bound ? 'm03-p01.html' : 'm02-p01.html';
      return true;
    }

() => {
      if (UI.failNext('send-code')) throw new Error('验证码未能准备好，请再试一次');
      next = issue(purpose, phoneValue(field), data);
      UI.toast('演示验证码：' + DEMO_CODE); return true;
    }

async () => {
        let challenge = readChallenge();
        if (code.value) {
          if (!challenge || challenge.phone !== phoneValue(phone) || !codeValid(code.value, challenge, 'register')) { UI.fieldError(code, '验证码不正确或已过期，请重新获取'); return false; }
          return finishRegistration({...challenge, nickname: nickname.value.trim()});
        }
        challenge = issue('register', phoneValue(phone), {nickname: nickname.value.trim(), completeRegistration: true});
        leave.commit(); return UI.go('m01-p07.html', {force: true});
      }

async () => {
        if (UI.failNext('verify')) throw new Error('暂时无法验证，请重试');
        if (code.value) {
          const challenge = readChallenge();
          if (challenge?.phone !== phoneValue(phone) || !codeValid(code.value.trim(), challenge, 'recovery')) { UI.fieldError(code, '验证码不正确或已过期'); return false; }
          putChallenge({...challenge, verified: true}); leave.commit(); return UI.go('m01-p05.html', {force: true});
        }
        issue('recovery', phoneValue(phone)); leave.commit(); return UI.go('m01-p07.html', {force: true});
      }

async () => {
        if (UI.failNext('verify')) throw new Error('验证没有完成，请重试');
        const latest=submissionChallenge(current);if(!latest)return false;
        if(latest.purpose==='register'&&latest.completeRegistration)return finishRegistration(latest);
        putChallenge({...latest,verified:true});
        if (latest.purpose === 'register') return UI.go('m01-p03.html', {force: true});
        return UI.go('m01-p05.html', {force: true});
      }

async () => {
        if(!submissionChallenge(challenge))return false;
        if (UI.failNext('reset')) throw new Error('重置没有完成，请重试');
        sessionStorage.setItem('dujia-prototype-reset-complete', String(Date.now())); sessionStorage.removeItem(KEY);
        leave.commit(); return UI.go('m01-p08.html', {force: true});
      }

async () => {
        if (UI.failNext('login')) throw new Error('暂时无法登录，请重试');
        const phone = sessionStorage.getItem('dujia-prototype-login-phone') || '13812345678';
        if (!await window.PrototypePreferences.login(phone)) return false;
        sessionStorage.removeItem('dujia-prototype-login-attempts'); return UI.go(UI.read('dujia-prototype-relationship')?.bound ? 'm03-p01.html' : 'm02-p01.html', {force: true});
      }

async()=>{
        if(UI.failNext('diary-save'))throw new Error('日记没有保存成功，请重试，内容仍保留');
        const current=existing?UI.currentItem(KEY,existing):null;if(existing&&!current)return false;if(current&&!PrototypePreferences.canView('record',current))throw new Error('这篇日记暂不可见，当前输入仍保留');
        const item={...current,id:existing?.id||'diary-'+crypto.randomUUID(),type:'diary',title,body,mood:form.elements.mood.value,visibility:form.elements.visibility.value,status,image,sampleImage,author:current?.author||nickname(),createdAt:current?.createdAt||Date.now(),updatedAt:Date.now(),comments:current?.comments||[],anniversaryId:current?.anniversaryId||anniversary?.id||null};
        if(!put(item))return false;leave.commit();UI.toast(status==='draft'?'草稿已保存':'日记已保存','success');
        if(existing?.status!=='published'||status!=='published')sessionStorage.setItem('dujia-diary-list-state',JSON.stringify({tab:status==='draft'?'draft':'all',visibility:'all'}));
        return UI.go(existing?.status==='published'&&status==='published'?route(item):'m03-p06.html',{force:true});
      }

async () => {
        if (UI.failNext('invite')) throw new Error('邀请暂时打不开，请重试');
        if (UI.read(PAIR)?.bound) { leave.commit(); return UI.go('m02-p09.html', {force:true}); }
        const invite = UI.read(INVITE);
        if (invite?.code === value && (invite.expiresAt <= Date.now() || ['accepted','expired'].includes(invite.status))) { leave.commit(); return UI.go('m02-p08.html', {force:true}); }
        if (value !== (invite?.code || code)) { UI.fieldError(fields[0], '邀请码没有找到，请核对或请 TA 重新分享', error); return false; }
        sessionStorage.setItem('dujia-prototype-incoming-invite', value); leave.commit(); return UI.go('m02-p04.html', {force:true});
      }

async () => {
        if (UI.failNext('profile')) throw new Error('资料没有保存成功，请重试');
        const pair = UI.read(PAIR, {bound:false}); if (!UI.write(PAIR, {...pair, profile:data})) return false;
        fields.forEach(name => { try { localStorage.setItem('dujia-profile-' + name, data[name]); } catch {} });
        UI.toast('小资料已保存', 'success'); leave.commit(); return UI.go(pair.bound ? 'm02-p05.html' : 'm02-p01.html', {force:true});
      }

() => {
      if (UI.failNext('remind')) throw new Error('提醒没有完成，请重试');
      if (!invite) throw new Error('未能准备邀请，请先恢复资料或返回重试');
      invite = {...invite, autoAt:Date.now()+1600}; if (!UI.write(INVITE, invite)) return false;
      paused = false; UI.toast('已提醒 TA 查看邀请'); return true;
    }
